const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, HeadingLevel, BorderStyle, WidthType, ShadingType,
  LevelFormat, PageBreak, TabStopType, TabStopPosition
} = require('docx');
const fs = require('fs');

const GOLD = "B8975A";
const GOLD_LIGHT = "F7EDD8";
const DARK = "1C1A16";
const GRAY_BG = "F5F4F0";
const BORDER_GRAY = "DDDDDD";
const WHITE = "FFFFFF";

const border = { style: BorderStyle.SINGLE, size: 1, color: BORDER_GRAY };
const borders = { top: border, bottom: border, left: border, right: border };
const noBorder = { style: BorderStyle.NONE, size: 0, color: "FFFFFF" };
const noBorders = { top: noBorder, bottom: noBorder, left: noBorder, right: noBorder };

function goldBar() {
  return new Paragraph({
    children: [new TextRun({ text: "" })],
    border: { bottom: { style: BorderStyle.SINGLE, size: 12, color: GOLD, space: 1 } },
    spacing: { before: 0, after: 240 }
  });
}

function spacer(pts = 120) {
  return new Paragraph({ children: [new TextRun("")], spacing: { before: 0, after: pts } });
}

function h1(text) {
  return new Paragraph({
    children: [new TextRun({ text, bold: true, size: 36, font: "Arial", color: DARK })],
    spacing: { before: 360, after: 120 }
  });
}

function h2(text) {
  return new Paragraph({
    children: [new TextRun({ text, bold: true, size: 26, font: "Arial", color: GOLD })],
    spacing: { before: 280, after: 100 }
  });
}

function h3(text) {
  return new Paragraph({
    children: [new TextRun({ text, bold: true, size: 22, font: "Arial", color: DARK })],
    spacing: { before: 200, after: 80 }
  });
}

function body(text, opts = {}) {
  return new Paragraph({
    children: [new TextRun({ text, size: 22, font: "Arial", color: DARK, ...opts })],
    spacing: { before: 60, after: 80 },
    ...(opts.para || {})
  });
}

function labelLine(label, text) {
  return new Paragraph({
    children: [
      new TextRun({ text: label + "  ", bold: true, size: 20, font: "Arial", color: GOLD }),
      new TextRun({ text, size: 20, font: "Arial", color: DARK })
    ],
    spacing: { before: 60, after: 60 }
  });
}

function callout(lines, label = null) {
  const children = [];
  if (label) children.push(
    new Paragraph({
      children: [new TextRun({ text: label, bold: true, size: 18, font: "Arial", color: GOLD, allCaps: true })],
      spacing: { before: 0, after: 80 }
    })
  );
  for (const line of lines) {
    children.push(new Paragraph({
      children: [new TextRun({ text: line, size: 21, font: "Arial", color: DARK, italics: true })],
      spacing: { before: 40, after: 40 }
    }));
  }
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [new TableRow({
      children: [new TableCell({
        borders: { top: { style: BorderStyle.SINGLE, size: 8, color: GOLD }, bottom: noBorder, left: noBorder, right: noBorder },
        shading: { fill: GOLD_LIGHT, type: ShadingType.CLEAR },
        margins: { top: 160, bottom: 160, left: 200, right: 200 },
        children
      })]
    })]
  });
}

function grayBox(lines, label = null) {
  const children = [];
  if (label) children.push(new Paragraph({
    children: [new TextRun({ text: label, bold: true, size: 18, font: "Arial", color: "666666", allCaps: true })],
    spacing: { before: 0, after: 80 }
  }));
  for (const line of lines) {
    children.push(new Paragraph({
      children: [new TextRun({ text: line, size: 21, font: "Arial", color: DARK })],
      spacing: { before: 40, after: 40 }
    }));
  }
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [new TableRow({
      children: [new TableCell({
        borders,
        shading: { fill: GRAY_BG, type: ShadingType.CLEAR },
        margins: { top: 140, bottom: 140, left: 200, right: 200 },
        children
      })]
    })]
  });
}

function bullet(text, indent = 0) {
  return new Paragraph({
    numbering: { reference: "bullets", level: indent },
    children: [new TextRun({ text, size: 22, font: "Arial", color: DARK })],
    spacing: { before: 40, after: 40 }
  });
}

function numbered(text, ref = "numbers") {
  return new Paragraph({
    numbering: { reference: ref, level: 0 },
    children: [new TextRun({ text, size: 22, font: "Arial", color: DARK })],
    spacing: { before: 40, after: 40 }
  });
}

function timeRow(time, title, content) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [1440, 7920],
    rows: [new TableRow({
      children: [
        new TableCell({
          borders: noBorders,
          shading: { fill: GOLD_LIGHT, type: ShadingType.CLEAR },
          margins: { top: 100, bottom: 100, left: 120, right: 120 },
          verticalAlign: "top",
          children: [
            new Paragraph({ children: [new TextRun({ text: time, bold: true, size: 18, font: "Arial", color: GOLD })], alignment: AlignmentType.CENTER }),
            new Paragraph({ children: [new TextRun({ text: title, size: 16, font: "Arial", color: "633806" })], alignment: AlignmentType.CENTER, spacing: { before: 40 } })
          ]
        }),
        new TableCell({
          borders: noBorders,
          margins: { top: 100, bottom: 100, left: 160, right: 80 },
          children: content.map(c => typeof c === 'string'
            ? new Paragraph({ children: [new TextRun({ text: c, size: 21, font: "Arial", color: DARK })], spacing: { before: 40, after: 40 } })
            : c
          )
        })
      ]
    })]
  });
}

function pageBreak() {
  return new Paragraph({ children: [new PageBreak()] });
}

function sectionDivider(title) {
  return [
    pageBreak(),
    new Paragraph({
      children: [new TextRun({ text: title, bold: true, size: 40, font: "Arial", color: WHITE })],
      shading: { fill: DARK, type: ShadingType.CLEAR },
      spacing: { before: 0, after: 0 },
      indent: { left: 360 },
    }),
    spacer(120)
  ];
}

// ============================================================
// DOCUMENT
// ============================================================

const doc = new Document({
  numbering: {
    config: [
      {
        reference: "bullets",
        levels: [{
          level: 0, format: LevelFormat.BULLET, text: "\u2022", alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 720, hanging: 360 } } }
        }, {
          level: 1, format: LevelFormat.BULLET, text: "\u25E6", alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 1080, hanging: 360 } } }
        }]
      },
      {
        reference: "numbers",
        levels: [{
          level: 0, format: LevelFormat.DECIMAL, text: "%1.", alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 720, hanging: 360 } } }
        }]
      }
    ]
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1440, right: 1440, bottom: 1440, left: 1440 }
      }
    },
    children: [

      // ===== COVER =====
      spacer(480),
      new Paragraph({
        children: [new TextRun({ text: "THE LUXORA COLLECTIVE", bold: true, size: 20, font: "Arial", color: GOLD, characterSpacing: 80 })],
        spacing: { before: 0, after: 80 }
      }),
      new Paragraph({
        children: [new TextRun({ text: "Workshop Launch Kit", bold: true, size: 52, font: "Arial", color: DARK })],
        spacing: { before: 0, after: 80 }
      }),
      new Paragraph({
        children: [new TextRun({ text: "60-Minute Script  |  5 Post-Event Emails  |  4 Promo Posts", size: 24, font: "Arial", color: "666666" })],
        spacing: { before: 0, after: 400 }
      }),
      goldBar(),
      spacer(120),
      new Paragraph({
        children: [new TextRun({ text: "THE ONE BIG IDEA:", bold: true, size: 22, font: "Arial", color: GOLD })],
        spacing: { before: 0, after: 80 }
      }),
      new Paragraph({
        children: [new TextRun({ text: "\"Your medspa is sitting on a revenue engine you haven't turned on yet, and it has nothing to do with adding more services or running more ads.\"", size: 26, font: "Arial", color: DARK, italics: true })],
        spacing: { before: 0, after: 400 }
      }),
      grayBox([
        "This kit contains three complete, ready-to-deploy assets:",
        "",
        "PART 1: The 60-Minute Workshop Script (word-for-word, in your voice)",
        "PART 2: The 5-Part Post-Event Email Sequence",
        "PART 3: The 4-Part Social Media Promo Pack"
      ]),

      // ===== PART 1: SCRIPT =====
      ...sectionDivider("PART 1: THE 60-MINUTE WORKSHOP SCRIPT"),

      new Paragraph({
        children: [new TextRun({ text: "Before you go live", bold: true, size: 26, font: "Arial", color: DARK })],
        spacing: { before: 0, after: 80 }
      }),
      body("This script is written in your voice with natural contractions. Do not read it verbatim. Read it once to internalize the beats, then speak from your own experience. The structure is the script. The words are yours."),
      spacer(80),
      grayBox([
        "TIMING GUIDE:  Segment 1 (0:00-0:08)  |  Segment 2 (0:08-0:18)  |  Segment 3 (0:18-0:42)  |  Segment 4 (0:42-0:52)  |  Segment 5 (0:52-1:00)",
        "PLATFORM: Zoom Webinar (recommended) or StreamYard into a private Facebook group",
        "RECORDING: Always record. This becomes your evergreen asset to run ads to."
      ], "Pre-flight checklist"),
      spacer(120),

      // SEGMENT 1
      h2("Segment 1: The Open (0:00 - 0:08)"),
      body("Do not open with \"Can everyone hear me?\" or \"Thanks so much for joining.\" Open on the first word of the hook. No warmup, no pleasantries. You want the first 10 seconds to feel different from every webinar they've ever sat through."),
      spacer(80),
      callout([
        "Before I get into anything today, I want you to sit with this for a second.",
        "",
        "The average medspa owner works 50-plus hours a week and still can't tell you what next month looks like. They've got a full schedule, a team they love, and a business that feels like it's always one bad week away from a crisis. And most of them have tried the stuff everyone tells you to try. More ads. A new service. A loyalty punch card. Maybe a discount to fill the slow weeks.",
        "",
        "And none of it stuck.",
        "",
        "I've sat across from enough of you to know that's not because you're doing something wrong. It's because nobody ever installed the right system. That's what today is about.",
        "",
        "[PAUSE. Let that land. Then:]",
        "",
        "My name is Bethany Anne. I'm the Co-Founder and CEO of The Luxora Collective. We work specifically with independent medspa owners doing somewhere between $500K and $3 million a year who've already proven there's a market for what they do, but growth feels like a grind instead of a system.",
        "",
        "In the next 60 minutes I'm going to walk you through the three-phase framework that changes that. Not theory. Not generic marketing advice. The exact phases we install with every client we take on, in sequence, starting on Day 1.",
        "",
        "[POLL THE ROOM]: Before we get into it, drop your name and city in the chat. I want to know who's in the room today.",
        "",
        "[Read 4-5 names and cities out loud. This creates immediate warmth and signals that you see them as individuals, not an audience.]"
      ], "Say this"),
      spacer(120),

      // SEGMENT 2
      h2("Segment 2: The Diagnosis (0:08 - 0:18)"),
      body("This is the most important segment of the entire workshop. Not because of what you teach, but because of how seen they feel. If they feel deeply understood before you offer anything, the rest is easy. The purchase decision happens here, not at the close."),
      spacer(80),
      callout([
        "I want to ask you something and I want you to be honest with yourself, not with me.",
        "",
        "Which of these sounds most like where you are right now?",
        "",
        "[DROP THESE IN THE CHAT AS A POLL OR READ THEM AND ASK FOR A RAISE OF HANDS / NUMBER IN CHAT:]",
        "",
        "A: Revenue plateau. You had a great year, maybe two. And then it just stopped. You don't know which lever to pull to get it moving again.",
        "",
        "B: Feast or famine. Packed one week, dead the next. You can't plan, can't breathe, can't sleep. The inconsistency is the thing that's killing you.",
        "",
        "C: Clients don't come back. They love the first appointment. Then they ghost. You don't know if they went somewhere else or just fell off. Either way, it stings.",
        "",
        "D: Staff won't sell. They're incredible injectors. But ask them to recommend a package or mention the membership at checkout and they freeze. It just isn't their personality, you tell yourself.",
        "",
        "E: The discount trap. You run a promo, it fills the books, the margin tanks, and the clients who came for the deal don't come back at full price.",
        "",
        "F: No time to fix any of it. You know you need systems. You're in the room doing injections all day. You don't have four hours to build a funnel. You just need someone to tell you what to do first.",
        "",
        "[PAUSE. Read the chat. Read 4-5 names back with their answer.]",
        "",
        "\"[Name] in Nashville said feast or famine. That's the one I hear most. [Name] in Scottsdale said staff won't sell. We're going to talk about exactly why that happens and why it's not actually a personality problem. It's a system problem.\"",
        "",
        "Here's what I want you to understand before we go any further.",
        "",
        "Every single one of those six things? They're symptoms of the same root cause. Your business doesn't have a marketing problem. It doesn't have a staff problem. It doesn't have an ad spend problem.",
        "",
        "It has a revenue architecture problem. The engine is missing.",
        "",
        "And here's the good news: the engine isn't that hard to install. You just need to know the sequence."
      ], "Say this"),
      spacer(120),

      // SEGMENT 3
      h2("Segment 3: The Three-Phase Framework (0:18 - 0:42)"),
      body("This is your teaching segment. You have 24 minutes across three phases, which is 8 minutes per phase. The rule is: one core concept, one mechanism, one story or example, one cost-of-inaction statement. Do not go deeper than that. The depth is what they get when they work with you. The goal is to make them feel the gap, not close it."),
      spacer(80),

      h3("PHASE 1: Capture the revenue that's already in the room (Days 1-30)"),
      callout([
        "Most medspa owners are so focused on getting new clients that they're completely ignoring the goldmine sitting in their current client base.",
        "",
        "Think about your top 30 clients. The ones who come in every 4 to 6 weeks without fail. The ones who tip well, refer their friends, and never push back on price. Now ask yourself: how many of them are on a membership program?",
        "",
        "[Pause for answers in chat]",
        "",
        "If the answer is zero or close to it, you're leaving somewhere between $8,000 and $15,000 in recurring revenue on the table every single month. Not someday. Right now.",
        "",
        "Here's what I mean by that mathematically. If you take your 30 best clients and convert half of them, just 15 people, onto a membership at $149 a month, that's $2,235 in recurring revenue. Every month. Before anyone books an appointment. Before you run a single ad.",
        "",
        "But that's just the membership piece. The system we install in Phase 1 also includes your package architecture, your upsell framework, your checkout culture, and AI-powered follow-up that catches every client who hasn't been in for more than 45 days and brings them back before they ever think to go somewhere else.",
        "",
        "The before picture: clients come in when they feel like it. Revenue is unpredictable. Your team has no framework for what to say beyond the service.",
        "",
        "The after picture: your client base has a heartbeat. You know the revenue coming in before the month starts. Your staff has a script. The follow-up runs itself.",
        "",
        "The cost of not doing this? Every month you operate without Phase 1 is a month that recurring revenue went somewhere else. Or just disappeared. That's $8,000 to $15,000 walking out the door. Month after month after month."
      ], "Say this"),
      spacer(80),

      h3("PHASE 2: Fill the room consistently (Days 31-60)"),
      callout([
        "Phase 1 captures what you already have. Phase 2 builds the engine that brings new clients to you on repeat, without you having to be the one chasing them.",
        "",
        "Most of the spa owners I talk to are doing all their own marketing. They're posting, they're DMing, they're running ads, they're in every Facebook group for medspa professionals trying to find the magic content angle. And the problem isn't effort. The problem is that they've made themselves the bottleneck.",
        "",
        "The system has to work when you're in the room doing what you're trained to do.",
        "",
        "Phase 2 installs three things: a reputation engine, a referral framework, and a partnership pipeline.",
        "",
        "The reputation engine is not \"just ask clients for reviews.\" It's a structured, timed sequence that captures feedback at the peak emotional moment after a service, routes it correctly based on sentiment, and turns your happiest clients into your loudest advocates. Automatically.",
        "",
        "The referral framework is not a punch card. It's a designed experience that makes referring feel like a gift, not a transaction. When it's done right, your clients become your salespeople. Not because you asked them to. Because you made it easy and it feels good.",
        "",
        "And the partnership pipeline is something most spa owners have never touched. One aligned partner, whether that's a fitness studio, a bridal boutique, a luxury hotel, a high-end hair salon, can send you 3 to 5 qualified clients a month. For free. Forever.",
        "",
        "The before picture: you're running ads to cold strangers and hoping. Your warmest leads are sitting inside your current clients' networks, completely untouched.",
        "",
        "The after picture: referrals are coming in without you asking. Your reputation online reflects what actually happens inside your walls. And you have two or three partners consistently sending you their clients.",
        "",
        "The cost of not doing this? You stay dependent on paid traffic. And as anyone running Meta ads right now knows, what worked last week might not work this week. The owners who are winning have more than one faucet running."
      ], "Say this"),
      spacer(80),

      h3("PHASE 3: Make it feel like a business, not a hustle (Days 61-90)"),
      callout([
        "This is the phase nobody talks about and it's the one that changes everything.",
        "",
        "By Day 60, if you've done Phases 1 and 2, you've got recurring revenue coming in, you've got referrals working, and you've got a reputation engine running. That's a business that's starting to breathe on its own.",
        "",
        "Phase 3 is about making it permanent. It's about locking in a team culture where selling feels natural, a client loyalty ritual that creates belonging, and a 90-Day Celebration Event that does something most spa owners have never done: it celebrates the journey your clients have been on with you.",
        "",
        "I know \"celebration event\" might sound optional. It's not. It's one of the highest-ROI activities we put inside the program. It re-activates dormant clients, it deepens loyalty with active ones, it creates content, and it generates word-of-mouth that money can't buy.",
        "",
        "But more than any single tactic in Phase 3, what this phase really installs is this: a documented growth engine that your business can run without you standing in the middle of every single thing.",
        "",
        "The before picture: it's all in your head. You're the bottleneck. If you're not there, things slow down or stop.",
        "",
        "The after picture: your team knows what to do. The systems run the day. You're the CEO of a growth engine, not the injector who also happens to manage a business.",
        "",
        "[PAUSE. Slow down here. Let the identity shift land.]",
        "",
        "That's the transformation this framework creates in 90 days. Not theory. Not some day. 90 days, with you doing the work and us being in the room with you the entire time."
      ], "Say this"),
      spacer(120),

      // SEGMENT 4
      h2("Segment 4: Proof and Possibility (0:42 - 0:52)"),
      body("This is where you shift the room from learning to wanting. One client story. Real numbers. Real timeline. Keep the identity of the client general enough to be relatable to everyone in the room."),
      spacer(80),
      callout([
        "I want to tell you about a client I'll call Sarah. Single-provider spa in the southeast. She'd been in business for four years, doing around $650K a year, and completely stuck. She'd tried ads, tried promotions, tried bringing in a second injector. Nothing moved the needle the way she needed it to.",
        "",
        "She came to us because she heard about the membership framework from another owner in her network. And honestly, her first question was: \"My clients aren't going to pay a monthly fee. They come in for Botox twice a year. That's it.\"",
        "",
        "I hear that every single time.",
        "",
        "Here's what actually happened. We designed her membership around what her clients were already doing, not what we wanted them to do. We priced it right. We trained her front desk on a three-sentence script for how to present it. And in 60 days, she had 34 members.",
        "",
        "34 members at $149 a month is $5,066 in recurring monthly revenue. That's revenue that shows up whether or not anyone books that week.",
        "",
        "But here's the part that mattered more than the number. Her staff started believing. Because when you have a framework, you're not asking them to \"be more salesy.\" You're giving them something to say. And that changed the energy in the spa.",
        "",
        "[PAUSE]",
        "",
        "Let me do some quick math with you. I want you to do this for your own spa in your head right now.",
        "",
        "What's your average service ticket? Hold that number.",
        "How many clients do you see in a month? Hold that number.",
        "Now imagine 20% of those clients are on a membership at $129 a month.",
        "",
        "What does that number look like? Because for most of the owners in this room, it's somewhere between $3,000 and $12,000 in additional recurring monthly revenue. From clients you already have. Without a single new ad.",
        "",
        "[Read a few chat responses if they share their math]",
        "",
        "Here's the objection I know some of you are sitting with right now. \"I've tried a membership before and it didn't work.\" Or: \"My clients are too independent. They don't want to be locked in.\"",
        "",
        "I want you to hear me on this. Most membership programs fail not because the concept doesn't work, but because the architecture was wrong. The pricing was off. The value exchange wasn't clear. The team didn't know how to present it. And nobody built in the offboarding experience that keeps people from feeling trapped.",
        "",
        "We've seen this enough times to know exactly where it breaks. And we've built the fix into every piece of the Phase 1 playbook."
      ], "Say this"),
      spacer(120),

      // SEGMENT 5
      h2("Segment 5: The Soft Close (0:52 - 1:00)"),
      body("Never pressure. Never fake scarcity. Never urgency language that feels manufactured. The close is a natural extension of who they've decided they want to be during the last 52 minutes. Plant the identity, then give them a step."),
      spacer(80),
      callout([
        "Here's where I want to land today.",
        "",
        "Everything we've covered, the membership, the referral engine, the partnerships, the celebration event, all of it is already built. It's already packaged. It's already tested. The playbooks exist. The scripts exist. The training exists.",
        "",
        "We don't go in and do it for you. That wouldn't work, because it needs to be yours. It needs to live inside your team, inside your culture, inside your brand. What we do is install it with you, week by week, call by call, over 90 days. And by the end, your team runs it.",
        "",
        "Here's what I want to offer everyone in this room today.",
        "",
        "I want to pull a Competitive Intelligence Briefing for your specific market. I'm going to look at what your top two or three competitors are doing, what's working, what's not, and which of these three phases is going to move the needle fastest for you specifically. This is not a sales call. There's no pitch. There's no pressure. You'll walk away with real data about your market whether you ever work with us or not.",
        "",
        "If you want one, drop your city and spa name in the chat right now and I'll have my team follow up to get you scheduled.",
        "",
        "[Pause. Read names from chat. Respond to a few directly.]",
        "",
        "[After 60-90 seconds:]",
        "",
        "For those of you who know you're ready to go deeper right now, the link to learn more about the 90-Day Growth Engine is in the chat. You can get all the details there and book your own call directly.",
        "",
        "[CLOSING IDENTITY STATEMENT, end the workshop on this:]",
        "",
        "Before I let you go, I want to say something I mean.",
        "",
        "The owners who are winning in this space right now are not the ones with the biggest following or the most beautiful suite. They're not the ones who are grinding the hardest. They're the ones who stopped treating their business like something to manage and started treating it like something to build.",
        "",
        "That's the shift. And it's available to every single person in this room.",
        "",
        "Thank you for being here today. I'll see some of you on the other side."
      ], "Say this"),
      spacer(80),
      grayBox([
        "After the close: stay on for 5-10 minutes for open Q&A. Keep it light. Don't go deep on tactics. If someone asks a question that gets into specifics, say: \"That's exactly what we'd cover in your briefing. Drop your spa in the chat and we'll get you on the calendar.\" Every tactical question is a CTA redirect."
      ], "Post-close Q&A note"),

      // ===== PART 2: EMAILS =====
      ...sectionDivider("PART 2: POST-EVENT EMAIL SEQUENCE"),

      body("Load all 5 emails in GHL before the workshop goes live. Set each to trigger from the registration date plus the timing below. Emails 1 and 1B send to attendees only. Emails 2-5 send to all registrants (showed up or not)."),
      spacer(80),

      // EMAIL 1
      h2("Email 1: Send 1 hour after the workshop ends"),
      grayBox([
        "SUBJECT: You showed up for your business today",
        "SEND TO: Attendees only",
        "TRIGGER: 1 hour after event end time"
      ], "Settings"),
      spacer(80),
      callout([
        "Hey [First Name],",
        "",
        "I just wanted to say, the fact that you showed up today says something about where you are as an owner.",
        "",
        "Most people talk about fixing the system. You actually blocked the time and showed up to learn how. That already puts you in a different category.",
        "",
        "Here's the recording from today if you want to go back through any of it: [RECORDING LINK]",
        "",
        "And if you want to take the next step, here's what I'd suggest:",
        "",
