        spacing: { before: 0, after: 400 }
      }),
      goldBar(),
      spacer(120),
      new Paragraph({
        children: [new TextRun({ text: "THE ONE BIG IDEA:", bold: true, size: 22, font: "Arial", color: GOLD })],
        spacing: { before: 0, after: 80 }
      }),
      new Paragraph({
        children: [new TextRun({ text: "\"Your medspa is sitting on a revenue engine you haven't turned on yet, and it has nothing to do with adding more services or running more ads.\"", size: 26, font: "Arial", color: DARK, italics: true })],
        spacing: { before: 0, after: 400 }
      }),
      grayBox([
        "This kit contains three complete, ready-to-deploy assets:",
        "",
        "PART 1: The 60-Minute Workshop Script (word-for-word, in your voice)",
