      numbered("Test Zoom or StreamYard link with audio and screen share the day before."),
      numbered("Run the workshop. Record everything."),
      numbered("Repurpose the recording: run ads to it, add it to the nurture sequence, clip the best 60-second moments for organic content."),
      spacer(80),

      grayBox([
        "Remember: the workshop is not the product. The workshop is the bridge. Every decision about content, pacing, and the close should be made with one question: does this move them closer to booking the briefing call? If it does, keep it. If it doesn't, cut it."
      ], "The only metric that matters"),

      spacer(120),
      new Paragraph({
        children: [new TextRun({ text: "theluxoracollective.co", size: 18, font: "Arial", color: GOLD })],
        alignment: AlignmentType.CENTER
      }),
      new Paragraph({
        children: [new TextRun({ text: "Bethany Anne, Co-Founder & CEO", size: 18, font: "Arial", color: "888888" })],
        alignment: AlignmentType.CENTER
      })

    ]
  }]
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync('/mnt/user-data/outputs/Luxora_Workshop_Kit.docx', buffer);
  console.log('Done');
