const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, HeadingLevel, BorderStyle, WidthType, ShadingType,
  LevelFormat, PageBreak, TabStopType, TabStopPosition
} = require('docx');
const fs = require('fs');

const GOLD = "B8975A";
const GOLD_LIGHT = "F7EDD8";
const DARK = "1C1A16";
const GRAY_BG = "F5F4F0";
const BORDER_GRAY = "DDDDDD";
const WHITE = "FFFFFF";

const border = { style: BorderStyle.SINGLE, size: 1, color: BORDER_GRAY };
const borders = { top: border, bottom: border, left: border, right: border };
const noBorder = { style: BorderStyle.NONE, size: 0, color: "FFFFFF" };
const noBorders = { top: noBorder, bottom: noBorder, left: noBorder, right: noBorder };

function goldBar() {
  return new Paragraph({
    children: [new TextRun({ text: "" })],
    border: { bottom: { style: BorderStyle.SINGLE, size: 12, color: GOLD, space: 1 } },
    spacing: { before: 0, after: 240 }
  });
}

function spacer(pts = 120) {
  return new Paragraph({ children: [new TextRun("")], spacing: { before: 0, after: pts } });
}

function h2(text) {
  return new Paragraph({
    children: [new TextRun({ text, bold: true, size: 26, font: "Arial", color: GOLD })],
    spacing: { before: 280, after: 100 }
  });
}

function h3(text) {
  return new Paragraph({
    children: [new TextRun({ text, bold: true, size: 22, font: "Arial", color: DARK })],
    spacing: { before: 200, after: 80 }
  });
}

function body(text) {
  return new Paragraph({
    children: [new TextRun({ text, size: 22, font: "Arial", color: DARK })],
    spacing: { before: 60, after: 80 }
  });
}

function callout(lines, label = null) {
  const children = [];
  if (label) children.push(
    new Paragraph({
      children: [new TextRun({ text: label, bold: true, size: 18, font: "Arial", color: GOLD, allCaps: true })],
      spacing: { before: 0, after: 80 }
    })
  );
  for (const line of lines) {
    children.push(new Paragraph({
      children: [new TextRun({ text: line, size: 21, font: "Arial", color: DARK, italics: true })],
      spacing: { before: 40, after: 40 }
    }));
  }
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [new TableRow({
      children: [new TableCell({
        borders: { top: { style: BorderStyle.SINGLE, size: 8, color: GOLD }, bottom: noBorder, left: noBorder, right: noBorder },
        shading: { fill: GOLD_LIGHT, type: ShadingType.CLEAR },
        margins: { top: 160, bottom: 160, left: 200, right: 200 },
        children
      })]
    })]
  });
}

function directorNote(text) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [new TableRow({
      children: [new TableCell({
        borders,
        shading: { fill: "E8F0E8", type: ShadingType.CLEAR },
        margins: { top: 100, bottom: 100, left: 180, right: 180 },
        children: [new Paragraph({
          children: [
            new TextRun({ text: "FILMING NOTE: ", bold: true, size: 18, font: "Arial", color: "2E5E2E" }),
            new TextRun({ text, size: 18, font: "Arial", color: "2E5E2E" })
          ],
          spacing: { before: 0, after: 0 }
        })]
      })]
    })]
  });
}

function grayBox(lines, label = null) {
  const children = [];
  if (label) children.push(new Paragraph({
    children: [new TextRun({ text: label, bold: true, size: 18, font: "Arial", color: "666666", allCaps: true })],
    spacing: { before: 0, after: 80 }
  }));
  for (const line of lines) {
    children.push(new Paragraph({
      children: [new TextRun({ text: line, size: 21, font: "Arial", color: DARK })],
      spacing: { before: 40, after: 40 }
    }));
  }
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [new TableRow({
      children: [new TableCell({
        borders,
        shading: { fill: GRAY_BG, type: ShadingType.CLEAR },
        margins: { top: 140, bottom: 140, left: 200, right: 200 },
        children
      })]
    })]
  });
}

function bullet(text) {
  return new Paragraph({
    numbering: { reference: "bullets", level: 0 },
    children: [new TextRun({ text, size: 22, font: "Arial", color: DARK })],
    spacing: { before: 40, after: 40 }
  });
}

function numbered(text) {
  return new Paragraph({
    numbering: { reference: "numbers", level: 0 },
    children: [new TextRun({ text, size: 22, font: "Arial", color: DARK })],
    spacing: { before: 40, after: 40 }
  });
}

function pageBreak() {
  return new Paragraph({ children: [new PageBreak()] });
}

function sectionDivider(title) {
  return [
    pageBreak(),
    new Paragraph({
      children: [new TextRun({ text: title, bold: true, size: 40, font: "Arial", color: WHITE })],
      shading: { fill: DARK, type: ShadingType.CLEAR },
      spacing: { before: 0, after: 0 },
      indent: { left: 360 },
    }),
    spacer(120)
  ];
}

const doc = new Document({
  numbering: {
    config: [
      {
        reference: "bullets",
        levels: [{
          level: 0, format: LevelFormat.BULLET, text: "\u2022", alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 720, hanging: 360 } } }
        }]
      },
      {
        reference: "numbers",
        levels: [{
          level: 0, format: LevelFormat.DECIMAL, text: "%1.", alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 720, hanging: 360 } } }
        }]
      }
    ]
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1440, right: 1440, bottom: 1440, left: 1440 }
      }
    },
    children: [

      // ===== COVER =====
      spacer(480),
      new Paragraph({
        children: [new TextRun({ text: "THE LUXORA COLLECTIVE", bold: true, size: 20, font: "Arial", color: GOLD, characterSpacing: 80 })],
        spacing: { before: 0, after: 80 }
      }),
      new Paragraph({
        children: [new TextRun({ text: "Workshop Launch Kit", bold: true, size: 52, font: "Arial", color: DARK })],
        spacing: { before: 0, after: 80 }
      }),
      new Paragraph({
        children: [new TextRun({ text: "Filmed Format Edition", size: 28, font: "Arial", color: "888888" })],
        spacing: { before: 0, after: 80 }
      }),
      new Paragraph({
        children: [new TextRun({ text: "60-Minute Script  |  5 Post-Event Emails  |  4 Promo Posts", size: 22, font: "Arial", color: "888888" })],
        spacing: { before: 0, after: 400 }
      }),
      goldBar(),
      spacer(120),
      new Paragraph({
        children: [new TextRun({ text: "THE ONE BIG IDEA:", bold: true, size: 22, font: "Arial", color: GOLD })],
        spacing: { before: 0, after: 80 }
      }),
      new Paragraph({
        children: [new TextRun({ text: "\"Your medspa is sitting on a revenue engine you haven't turned on yet, and it has nothing to do with adding more services or running more ads.\"", size: 26, font: "Arial", color: DARK, italics: true })],
        spacing: { before: 0, after: 400 }
      }),
      grayBox([
        "This is the filmed format version of the Workshop Kit. All live/interactive language has been replaced with prompts the viewer answers in their own head or on paper. No poll responses, no reading names from chat, no Q&A after the close.",
        "",
        "PART 1: The 60-Minute Workshop Script (filmed, word-for-word, in your voice)",
        "PART 2: The 5-Part Post-Event Email Sequence",
        "PART 3: The 4-Part Social Media Promo Pack"
      ]),

      // ===== PART 1: SCRIPT =====
      ...sectionDivider("PART 1: THE 60-MINUTE WORKSHOP SCRIPT"),

      body("This script is written in your voice with natural contractions. Do not read it verbatim. Internalize the beats, then speak from your experience. Every [PAUSE] note is a real instruction: stop talking, look at the camera, let it land before moving on."),
      spacer(40),
      directorNote("This is a pre-recorded workshop. All audience participation is designed as a self-directed prompt. Viewers answer in their head or pause and write it down. You never acknowledge a specific response. Speak as if the room is full and everyone is nodding."),
      spacer(80),
      grayBox([
        "TIMING:  Segment 1 (0:00-0:08)  |  Segment 2 (0:08-0:18)  |  Segment 3 (0:18-0:42)  |  Segment 4 (0:42-0:52)  |  Segment 5 (0:52-1:00)",
        "FORMAT: Talking head to camera. Slides can support each phase. Keep slides minimal.",
        "RECORD: One full take, then edit for energy. The recording is your evergreen asset."
      ], "Pre-flight"),
      spacer(120),

      // SEGMENT 1
      h2("Segment 1: The Open (0:00 - 0:08)"),
      body("Do not open with \"Welcome, everyone\" or \"Thanks for watching.\" Open on the first word of the hook. No warmup."),
      spacer(60),
      callout([
        "Before I get into anything today, I want you to sit with something for a second.",
        "",
        "The average medspa owner works 50-plus hours a week and still can't tell you what next month looks like. They've got a full schedule, a team they love, and a business that feels like it's always one bad week away from a crisis. And most of them have tried the stuff everyone tells you to try. More ads. A new service. A loyalty punch card. Maybe a discount to fill the slow weeks.",
        "",
        "And none of it stuck.",
        "",
        "I've sat across from enough of you to know that's not because you're doing something wrong. It's because nobody ever installed the right system. That's what today is about.",
        "",
        "[PAUSE. Hold eye contact with the camera for two full seconds before continuing.]",
        "",
        "My name is Bethany Anne. I'm the Co-Founder and CEO of The Luxora Collective. We work specifically with independent medspa owners doing somewhere between $500K and $3 million a year, owners who've already proven there's a market for what they do, but growth feels like a grind instead of a system.",
        "",
        "In the next 60 minutes I'm going to walk you through the three-phase framework that changes that. Not theory. Not generic marketing advice. The exact phases we install with every single client we take on, in sequence, starting on Day 1.",
        "",
        "So before we get into it, I want you to do one thing. Grab a piece of paper or open the notes app on your phone. You're going to want to write some of this down, and I'm going to ask you a few questions along the way that are worth actually answering, not just thinking about.",
        "",
        "Alright. Let's get into it."
      ], "Say this"),
      spacer(120),

      // SEGMENT 2
      h2("Segment 2: The Diagnosis (0:08 - 0:18)"),
      body("This is the most important segment of the entire workshop. Not because of what you teach, but because of how seen they feel. Speak slowly here. Let each pain point land fully before moving to the next."),
      spacer(60),
      directorNote("Read each pain point directly to camera with a brief pause after each. You want the viewer to have a moment to register 'yes, that's me' before you move on. Do not rush this segment."),
      spacer(60),
      callout([
        "I want to ask you something, and I want you to be honest with yourself, not with me.",
        "",
        "I'm going to read through six things that medspa owners tell me all the time. I want you to notice which one hits closest to home right now. You don't have to pick just one. Some of you are going to hear all six and want to raise your hand every time.",
        "",
        "[PAUSE]",
        "",
        "The first one: revenue plateau. You had a great year, maybe two. And then it just stopped. You don't know which lever to pull to get it moving again.",
        "",
        "[PAUSE]",
        "",
        "The second: feast or famine. Packed one week, dead the next. You can't plan, can't breathe, can't sleep. The inconsistency is the thing that's slowly killing you.",
        "",
        "[PAUSE]",
        "",
        "The third: clients don't come back. They love the first appointment. Then they ghost. You don't know if they went somewhere else or just fell off. Either way, it stings.",
        "",
        "[PAUSE]",
        "",
        "The fourth: staff won't sell. They're incredible injectors. But ask them to recommend a package or mention a membership at checkout and they freeze. It just isn't their personality, you tell yourself.",
        "",
        "[PAUSE]",
        "",
        "The fifth: the discount trap. You run a promo, it fills the books, the margin tanks, and the clients who came for the deal don't come back at full price.",
        "",
        "[PAUSE]",
        "",
        "And the sixth: no time to fix any of it. You know you need systems. You're in the room doing injections all day. You don't have four hours to build a funnel. You just need someone to tell you what to do first.",
        "",
        "[PAUSE. Slower now.]",
        "",
        "If you heard yourself in any of those, I want you to write down the one that resonates the most. That one is your entry point into what I'm about to share with you.",
        "",
        "[PAUSE]",
        "",
        "Here's what I want you to understand before we go any further.",
        "",
        "Every single one of those six things? They're symptoms of the same root cause. Your business doesn't have a marketing problem. It doesn't have a staff problem. It doesn't have an ad spend problem.",
        "",
        "It has a revenue architecture problem. The engine is missing.",
        "",
        "And here's the good news: the engine isn't that hard to install. You just need to know the sequence."
      ], "Say this"),
      spacer(120),

      // SEGMENT 3
      h2("Segment 3: The Three-Phase Framework (0:18 - 0:42)"),
      body("You have 24 minutes across three phases, roughly 8 minutes each. One core concept, one mechanism, one example, one cost-of-inaction statement per phase. Teach the concept, not the tactic. The tactic is what they get when they work with you."),
      spacer(60),

      h3("PHASE 1: Capture the revenue that's already in the room (Days 1-30)"),
      callout([
        "Most medspa owners are so focused on getting new clients that they're completely overlooking the goldmine sitting right inside their current client base.",
        "",
        "I want you to do a quick exercise. Think about your top 30 clients. The ones who come in every 4 to 6 weeks without fail. The ones who tip well, refer their friends, and never push back on price.",
        "",
        "Now ask yourself: how many of them are on a membership program?",
        "",
        "[PAUSE. Hold the question. Give them 3-4 seconds to actually think about it.]",
        "",
        "If the answer is zero or close to it, you're leaving somewhere between $8,000 and $15,000 in recurring revenue on the table every single month. Not someday. Right now.",
        "",
        "Here's what I mean by that. If you take your 30 best clients and convert half of them, just 15 people, onto a membership at $149 a month, that's $2,235 in recurring revenue. Every month. Before anyone books an appointment. Before you run a single ad.",
        "",
        "But that's just the membership piece. The system we install in Phase 1 also includes your package architecture, your upsell framework, your checkout culture, and AI-powered follow-up that catches every client who hasn't been in for more than 45 days and brings them back before they ever think to go somewhere else.",
        "",
        "The before picture: clients come in when they feel like it. Revenue is unpredictable. Your team has no framework for what to say beyond the service itself.",
        "",
        "The after picture: your client base has a heartbeat. You know the revenue coming in before the month starts. Your staff has a script. The follow-up runs itself.",
        "",
        "The cost of not doing this: every month you operate without Phase 1 is a month that recurring revenue went somewhere else. Or just disappeared. That's $8,000 to $15,000 walking out the door, month after month after month.",
        "",
        "Write this down: your current clients are your fastest path to predictable revenue. Not new ads. Not new services. The people already in your chairs."
      ], "Say this"),
      spacer(80),

      h3("PHASE 2: Fill the room consistently (Days 31-60)"),
      callout([
        "Phase 1 captures what you already have. Phase 2 builds the engine that brings new clients to you on repeat, without you being the one chasing them.",
        "",
        "Here's a question I want you to sit with. How many hours a week are you personally spending on marketing? Posting, DMing, responding to comments, trying to figure out what to say next?",
        "",
        "[PAUSE. Hold it.]",
        "",
        "Now ask yourself: is that a good use of your time as the owner of this business?",
        "",
        "[PAUSE]",
        "",
        "Most of the spa owners I work with have made themselves the bottleneck. And the problem isn't effort. It's that the system has to work when you're in the room doing what you're actually trained to do.",
        "",
        "Phase 2 installs three things. A reputation engine, a referral framework, and a partnership pipeline.",
        "",
        "The reputation engine isn't just asking clients for reviews. It's a structured, timed sequence that captures feedback at the peak emotional moment after a service, routes it correctly based on the sentiment, and turns your happiest clients into your loudest advocates. Automatically.",
        "",
        "The referral framework isn't a punch card. It's a designed experience that makes referring feel like a gift, not a transaction. When it's done right, your clients become your salespeople. Not because you asked them to. Because you made it easy and it feels good.",
        "",
        "And the partnership pipeline is something most spa owners have never touched. One aligned partner, whether that's a fitness studio, a bridal boutique, a luxury hotel, or a high-end hair salon, can send you 3 to 5 qualified clients a month. For free. Forever.",
        "",
        "The before picture: you're running ads to cold strangers and hoping. Your warmest leads are sitting inside your current clients' networks, completely untouched.",
        "",
        "The after picture: referrals are coming in without you asking. Your reputation online reflects what actually happens inside your walls. And you have two or three partners consistently sending you their clients.",
        "",
        "The cost of not doing this: you stay dependent on paid traffic. And as anyone running Meta ads right now knows, what worked last week might not work this week. The owners who are winning have more than one faucet running.",
        "",
        "Write this down: one partnership done right is worth more than six months of ad spend."
      ], "Say this"),
      spacer(80),

      h3("PHASE 3: Make it feel like a business, not a hustle (Days 61-90)"),
      callout([
        "This is the phase nobody talks about, and it's the one that changes everything.",
        "",
        "By Day 60, if you've done Phases 1 and 2, you've got recurring revenue coming in, you've got referrals working, and you've got a reputation engine running. That's a business that's starting to breathe on its own.",
        "",
        "Phase 3 is about making it permanent. It's about locking in a team culture where selling feels natural, a client loyalty ritual that creates belonging, and a 90-Day Celebration Event that does something most spa owners have never done: it celebrates the journey your clients have been on with you.",
        "",
        "I know \"celebration event\" might sound optional. It's not. It's one of the highest-ROI activities we put inside the program. It re-activates dormant clients, it deepens loyalty with active ones, it creates content, and it generates word-of-mouth that money can't buy.",
        "",
        "But more than any single tactic, what Phase 3 really installs is this: a documented growth engine that your business can run without you standing in the middle of every single thing.",
        "",
        "I want you to think about what that would actually feel like.",
        "",
        "[PAUSE. Slow down. Give them a genuine moment here.]",
        "",
        "What would it feel like to walk into your spa on a Tuesday and have everything already handled? The follow-ups done, the reschedules covered, the membership inquiry responded to? No one calling you. No one waiting on a decision from you.",
        "",
        "That's not a fantasy. That's what a documented system produces.",
        "",
        "The before picture: it's all in your head. You're the bottleneck. If you're not there, things slow down or stop.",
        "",
        "The after picture: your team knows what to do. The systems run the day. You're the CEO of a growth engine, not the injector who also happens to manage a business.",
        "",
        "[PAUSE. Slower still. Let the identity shift land.]",
        "",
        "That is the transformation this framework creates in 90 days. Not theory. Not someday. 90 days, with you doing the work and us being in the room with you the entire time.",
        "",
        "Write this down: the goal isn't to work harder inside your business. It's to build a business that works."
      ], "Say this"),
      spacer(120),

      // SEGMENT 4
      h2("Segment 4: Proof and Possibility (0:42 - 0:52)"),
      body("This is where you shift the room from learning to wanting. One client story, real numbers, real timeline. Then a guided math exercise where the viewer does the calculation for their own spa."),
      spacer(60),
      directorNote("For the math exercise, pause genuinely after each question. Look slightly down as if you're doing the math yourself, then look back up. It cues the viewer to actually stop and think."),
      spacer(60),
      callout([
        "I want to tell you about a client I'll call Sarah. Single-provider spa in the southeast. She'd been in business for four years, doing around $650K a year, and completely stuck. She'd tried ads, tried promotions, tried bringing in a second injector. Nothing moved the needle the way she needed it to.",
        "",
        "She came to us because she'd heard about the membership framework from another owner in her network. And her first question to me was: \"My clients aren't going to pay a monthly fee. They come in for Botox twice a year. That's it.\"",
        "",
