{"language": "javascript", "code": "const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, HeadingLevel, BorderStyle, WidthType, ShadingType,
  LevelFormat, PageBreak, TabStopType, TabStopPosition
} = require('docx');
const fs = require('fs');

const GOLD = "B8975A";
const GOLD_LIGHT = "F7EDD8";
const DARK = "1C1A16";
const GRAY_BG = "F5F4F0";
const BORDER_GRAY = "DDDDDD";
const WHITE = "FFFFFF";

const border = { style: BorderStyle.SINGLE, size: 1, color: BORDER_GRAY };
const borders = { top: border, bottom: border, left: border, right: border };
const noBorder = { style: BorderStyle.NONE, size: 0, color: "FFFFFF" };
const noBorders = { top: noBorder, bottom: noBorder, left: noBorder, right: noBorder };

function goldBar() {
  return new Paragraph({
    children: [new TextRun({ text: "" })],
    border: { bottom: { style: BorderStyle.SINGLE, size: 12, color: GOLD, space: 1 } },
    spacing: { before: 0, after: 240 }
  });
}

function spacer(pts = 120) {
  return new Paragraph({ children: [new TextRun("")], spacing: { before: 0, after: pts } });
}

function h2(text) {
  return new Paragraph({
    children: [new TextRun({ text, bold: true, size: 26, font: "Arial", color: GOLD })],
    spacing: { before: 280, after: 100 }
  });
}

function h3(text) {
  return new Paragraph({
    children: [new TextRun({ text, bold: true, size: 22, font: "Arial", color: DARK })],
    spacing: { before: 200, after: 80 }
  });
}

function body(text) {
  return new Paragraph({
    children: [new TextRun({ text, size: 22, font: "Arial", color: DARK })],
    spacing: { before: 60, after: 80 }
  });
}

function callout(lines, label = null) {
  const children = [];
  if (label) children.push(
    new Paragraph({
      children: [new TextRun({ text: label, bold: true, size: 18, font: "Arial", color: GOLD, allCaps: true })],
      spacing: { before: 0, after: 80 }
    })
  );
  for (const line of lines) {
    children.push(new Paragraph({
      children: [new TextRun({ text: line, size: 21, font: "Arial", color: DARK, italics: true })],
      spacing: { before: 40, after: 40 }
    }));
  }
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [new TableRow({
      children: [new TableCell({
        borders: { top: { style: BorderStyle.SINGLE, size: 8, color: GOLD }, bottom: noBorder, left: noBorder, right: noBorder },
        shading: { fill: GOLD_LIGHT, type: ShadingType.CLEAR },
        margins: { top: 160, bottom: 160, left: 200, right: 200 },
        children
      })]
    })]
  });
}

function directorNote(text) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [new TableRow({
      children: [new TableCell({
        borders,
        shading: { fill: "E8F0E8", type: ShadingType.CLEAR },
        margins: { top: 100, bottom: 100, left: 180, right: 180 },
        children: [new Paragraph({
          children: [
            new TextRun({ text: "FILMING NOTE: ", bold: true, size: 18, font: "Arial", color: "2E5E2E" }),
            new TextRun({ text, size: 18, font: "Arial", color: "2E5E2E" })
          ],
          spacing: { before: 0, after: 0 }
        })]
      })]
    })]
  });
}

function grayBox(lines, label = null) {
  const children = [];
  if (label) children.push(new Paragraph({
    children: [new TextRun({ text: label, bold: true, size: 18, font: "Arial", color: "666666", allCaps: true })],
    spacing: { before: 0, after: 80 }
  }));
  for (const line of lines) {
    children.push(new Paragraph({
      children: [new TextRun({ text: line, size: 21, font: "Arial", color: DARK })],
      spacing: { before: 40, after: 40 }
    }));
  }
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [new TableRow({
      children: [new TableCell({
        borders,
        shading: { fill: GRAY_BG, type: ShadingType.CLEAR },
        margins: { top: 140, bottom: 140, left: 200, right: 200 },
        children
      })]
    })]
  });
}

function bullet(text) {
  return new Paragraph({
    numbering: { reference: "bullets", level: 0 },
    children: [new TextRun({ text, size: 22, font: "Arial", color: DARK })],
    spacing: { before: 40, after: 40 }
  });
}

function numbered(text) {
  return new Paragraph({
    numbering: { reference: "numbers", level: 0 },
    children: [new TextRun({ text, size: 22, font: "Arial", color: DARK })],
    spacing: { before: 40, after: 40 }
  });
}

function pageBreak() {
  return new Paragraph({ children: [new PageBreak()] });
}

function sectionDivider(title) {
  return [
    pageBreak(),
    new Paragraph({
      children: [new TextRun({ text: title, bold: true, size: 40, font: "Arial", color: WHITE })],
      shading: { fill: DARK, type: ShadingType.CLEAR },
      spacing: { before: 0, after: 0 },
      indent: { left: 360 },
    }),
    spacer(120)
  ];
}

const doc = new Document({
  numbering: {
    config: [
      {
        reference: "bullets",
        levels: [{
          level: 0, format: LevelFormat.BULLET, text: "\u2022", alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 720, hanging: 360 } } }
        }]
      },
      {
